nlang_code:
mod blocks NotarizationEnvelope {
  props {
    aph_version: str,
    context: Directional<str>,
    type: Directional<str>,
    id: str,
    // In PrincipalSigned mode the issuer is the HUMAN principal's DID,
    // not the notary's: the human is the issuing authority in substance,
    // the notary a witness (§7.3.1).
    issuer: str,
    valid_from: str,
    valid_until: str,
    credential_subject: CredentialSubject,
    #[optional(true)]
    linked_mandate: LinkedMandate,
    // On the wire: a two-element ARRAY — the principal proof, then the
    // notary countersignature linked by `previous_proof`.
    proof: EnvelopeProof,
  }
}
